CREATE TABLE wb.sst_identity(project_id text NOT NULL,version_id text NOT NULL,sst_id text NOT NULL CHECK(btrim(sst_id)<>''),source_system text NOT NULL CHECK(btrim(source_system)<>''),source_namespace text NOT NULL CHECK(btrim(source_namespace)<>''),source_object_id text NOT NULL CHECK(btrim(source_object_id)<>''),source_revision text NOT NULL CHECK(btrim(source_revision)<>''),source_ref text NOT NULL CHECK(btrim(source_ref)<>''),PRIMARY KEY(project_id,version_id,sst_id),UNIQUE(project_id,sst_id),UNIQUE(project_id,version_id,source_system,source_namespace,source_object_id),FOREIGN KEY(project_id,version_id) REFERENCES wb.system_version);
CREATE TABLE wb.verified_sst_link(project_id text NOT NULL,batch_id text NOT NULL,requirement_id text NOT NULL,version_id text NOT NULL,sst_id text NOT NULL,source_link_ref text NOT NULL CHECK(btrim(source_link_ref)<>''),verified_source_revision text NOT NULL CHECK(btrim(verified_source_revision)<>''),PRIMARY KEY(project_id,batch_id,requirement_id,version_id,sst_id),FOREIGN KEY(project_id,batch_id,requirement_id,version_id) REFERENCES wb.batch_requirement_version,FOREIGN KEY(project_id,version_id,sst_id) REFERENCES wb.sst_identity);
CREATE TABLE wb.batch_requirement_version_sst(project_id text NOT NULL,batch_id text NOT NULL,requirement_id text NOT NULL,version_id text NOT NULL,sst_id text NOT NULL,PRIMARY KEY(project_id,batch_id,requirement_id,version_id,sst_id),FOREIGN KEY(project_id,batch_id,requirement_id,version_id,sst_id) REFERENCES wb.verified_sst_link);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['sst_identity','verified_sst_link','batch_requirement_version_sst'] LOOP EXECUTE format('ALTER TABLE wb.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY read_scope ON wb.%I FOR SELECT USING(wb.allowed(project_id,false))',t); EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON wb.%I FOR EACH ROW EXECUTE FUNCTION wb.reject_history_change()',t); END LOOP; END $$;
CREATE POLICY write_scope ON wb.batch_requirement_version_sst FOR INSERT WITH CHECK(wb.allowed(project_id,true));
